mapper.select:
SELECT id, serial_id, transfer_id, source_warehouse_id, target_warehouse_id, from_epoch, to_epoch, state, source_release_ref, target_receipt_ref, prepare_operation_id, version
FROM serial_transfer
WHERE enterprise_id=#{enterpriseId}
AND sku_id=#{skuId}
AND normalized_serial=#{serial}
AND transfer_id=#{transferId} FOR UPDATE

SELECT id, serial_id, transfer_id, source_warehouse_id, target_warehouse_id, from_epoch, to_epoch, state, source_release_ref, target_receipt_ref, prepare_operation_id, version
FROM serial_transfer
WHERE enterprise_id=#{enterpriseId}
AND sku_id=#{skuId}
AND normalized_serial=#{serial}
AND transfer_id=#{transferId}

mapper.update:
UPDATE serial_transfer
SET state=#{state}, source_release_ref=#{releaseRef}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND sku_id=#{skuId}
AND normalized_serial=#{serial}
AND transfer_id=#{transferId}
AND state=#{fromState}

UPDATE serial_transfer
SET state=#{state}, target_receipt_ref=#{receiptRef}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND sku_id=#{skuId}
AND normalized_serial=#{serial}
AND transfer_id=#{transferId}
AND state=#{fromState}

UPDATE serial_transfer
SET state='COMPLETED', target_receipt_ref=#{receiptRef}, to_epoch=#{toEpoch}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND sku_id=#{skuId}
AND normalized_serial=#{serial}
AND transfer_id=#{transferId}
AND state='RECEIVING'
